import {lensCases,lensSource} from './lens-bench-content.mjs';
import {newLensWork,changeLensWork,lensViewsView,lastLensView,keepLensView,lensMetrics,projectLensPoint} from './lens-bench-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x);
const button=(attrs,label,on=false)=>`<button type="button" class="${on?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
let visit=null,figureId=0;
export function resetLensBench(){visit=null;}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner)visit={book,owner,screen:'draft',active:'crossed',card:null,slots:new Map(),copies:new Map(),readonly:new Map(),page:null,chooser:false};return visit;}
function makeSlot(source,work){return {source:clone(source),work:clone(work||newLensWork(source)),turn:0,help:false,limits:false,credit:false,status:''};}
function slot(v){return v.screen==='card'?v.readonly.get(v.card):v.slots.get(v.active)||v.copies.get(v.active);}
function draft(v,id){if(!v.slots.has(id))v.slots.set(id,makeSlot(lensSource(id)));v.active=id;v.screen='draft';}
function settings(s,w){const o=s.objectives.find(o=>o.id===w.objectiveId),f=s.focus.find(f=>f.id===w.focusId),m=lensMetrics(s,w);return `${o.label} · ${s.eyepiece} × ${o.power} = ${m.total}× total. Focus: ${f.label}. Field diameter: ${Number(m.diameter.toPrecision(5))} drawing units.`;}
function mark(m,s,v){const p=projectLensPoint(s,v,m),k=lensMetrics(s,v).scale,r=m.size*k,x=p.x,y=p.y;let path;if(m.art==='ring')return `<circle data-lens-mark="${esc(m.id)}" cx="${x}" cy="${y}" r="${r}"/>`;if(m.art==='box')return `<rect data-lens-mark="${esc(m.id)}" x="${x-r}" y="${y-r}" width="${2*r}" height="${2*r}"/>`;if(m.art==='cross')path=`M${x-r} ${y}H${x+r}M${x} ${y-r}V${y+r}`;else path=`M${x-r} ${y-r/2}L${x-r/2} ${y+r/2} ${x} ${y-r/2} ${x+r/2} ${y+r/2} ${x+r} ${y-r/2}`;return `<path data-lens-mark="${esc(m.id)}" d="${path}"/>`;}
function drawing(s,v,label,interactive=false){const uid=`lens-figure-${++figureId}`,m=lensMetrics(s,v),t=s.marks.find(t=>t.id===s.targetId),p=projectLensPoint(s,v,t),edge=projectLensPoint(s,v,{x:0,y:0}),limited=m.sigma>200;return `<figure class="lens-drawing"><figcaption>${esc(label)}</figcaption><svg ${interactive?'data-lens-field':''} viewBox="0 0 400 400" role="img" aria-label="${esc(`Drawn practice pattern. ${settings(s,v)}`)}"><defs><clipPath id="${uid}-clip"><circle cx="200" cy="200" r="200"/></clipPath>${m.sigma>0&&!limited?`<filter id="${uid}-blur" filterUnits="userSpaceOnUse" x="0" y="0" width="400" height="400"><feGaussianBlur stdDeviation="${m.sigma}"/></filter>`:''}</defs><g clip-path="url(#${uid}-clip)"><rect width="400" height="400" fill="#e9ede7"/>${limited?'<rect width="400" height="400" fill="#e9ede7"/>':`<g${m.sigma>0?` filter="url(#${uid}-blur)"`:''}><rect x="${edge.x}" y="${edge.y}" width="${s.world.width*m.scale}" height="${s.world.height*m.scale}" fill="#fffdf2" stroke="#a57a34" stroke-width="2"/><g fill="none" stroke="#183f39" stroke-width="${1.5*m.scale}" stroke-linejoin="round">${s.marks.map(t=>mark(t,s,v)).join('')}</g></g>`}<circle data-lens-target cx="${p.x}" cy="${p.y}" r="${1.25*t.size*m.scale}" fill="none" stroke="#3d6b7a" stroke-width="2" stroke-dasharray="4 4"/></g><circle cx="200" cy="200" r="199" fill="none" stroke="#183f39" stroke-width="2"/></svg>${limited?'<p>Blur exceeds this model’s display range. Your kept settings stay unchanged.</p>':''}<p class="lens-caption">Drawn practice pattern</p><p class="lens-mark-legend">Marked patch: ${esc(t.label)} · blue dashed ring added by the game.</p><p class="lens-settings">${esc(settings(s,v))}</p><p class="lens-edge"><span aria-hidden="true">━</span> Edge of the drawn practice pattern</p></figure>`;}
function photo(s,w,activeControls=''){const p=s.photo,z=w.photoView.zoom,c=w.photoView;return `<figure class="lens-photograph" data-lens-photo-figure><div class="lens-photo-window" style="aspect-ratio:3264 / 1840"><img data-lens-photo-image src="assets/lens-bench/onion-epidermis.jpg" loading="lazy" width="3264" height="1840" alt="${esc(p.alt)}" style="width:${z*100}%;height:${z*100}%;left:${(0.5-c.x*z)*100}%;top:${(0.5-c.y*z)*100}%"><p class="lens-photo-fallback" hidden>The photograph could not be loaded. Its source description and credit are below.</p></div>${activeControls}<figcaption><strong>${esc(p.title)}</strong><p>${esc(p.caption)}</p><p>${esc(p.captureLabel)} · Digital enlargement: ${z===1?'Whole photo':`${z} times`}</p><p>Photographer’s title: ${esc(p.sourceTitle)}</p><p>${esc(p.credit)} ${esc(p.license)}</p><p>${esc(p.notice)}</p></figcaption></figure>`;}
function arrows(attr){return `<div class="lens-arrows" aria-label="Move the view">${['up','left','down','right'].map(d=>button(`${attr}="${d}"`,`Look ${d}`)).join('')}</div>`;}
function controls(s,work){const w=work.view,f=s.focus.findIndex(f=>f.id===w.focusId);return `<section class="lens-controls" aria-label="Practice view controls"><h3>Find a field</h3><p>Use the arrows, or tap inside the circle to center that point.</p>${arrows('data-lens-pan')}<h3>Choose an objective</h3><div class="lens-objectives">${s.objectives.map(o=>button(`data-lens-objective="${esc(o.id)}" aria-pressed="${w.objectiveId===o.id}"`,`${o.label} · ${s.eyepiece} × ${o.power} = ${s.eyepiece*o.power}× total`,w.objectiveId===o.id)).join('')}</div><h3>Turn focus</h3><p>${esc(s.focus[f].label)}</p><div class="lens-actions">${button(`data-lens-focus="-1"${f===0?' disabled':''}`,'Turn focus left')}${button(`data-lens-focus="1"${f===s.focus.length-1?' disabled':''}`,'Turn focus right')}</div>${button('data-lens-pin',work.pin?'Replace pin':'Pin this view')}</section>`;}
function activePage(a,readonly=false,copyLabel='Work on a copy'){const s=a.source,w=a.work;return `<h2 id="lens-title" tabindex="-1">${esc(s.title)}</h2>${readonly?`<div class="lens-notice"><p>Kept view · these settings and shown help stay unchanged.</p>${button('data-lens-copy',copyLabel)}</div>`:''}<nav class="lens-actions lens-turns" aria-label="Lens Bench turns">${['Viewfinder','Compare views','Photograph'].map((t,i)=>button(`data-lens-turn="${i}" aria-current="${a.turn===i?'step':'false'}"`,t,a.turn===i)).join('')}</nav><p>${a.turn===0?esc(s.context):a.turn===1?'What changed between these views? Compare one setting at a time if you want to investigate it.':'Look at a real image, separate from the practice drawing.'}</p>${readonly?'':button('data-lens-keep','Keep this view',true)}<p id="lens-status" role="status" tabindex="-1">${esc(a.status)}</p>${a.turn===0?`<div class="lens-workspace">${drawing(s,w.view,'Your practice view',!readonly)}${readonly?'':controls(s,w)}</div><p>${esc(s.annotation)}</p>`:a.turn===1?`${w.pin?`<div class="lens-comparison">${drawing(s,w.pin,'Pinned practice view')}${drawing(s,w.view,'Current practice view')}</div>`:`<p>${readonly?'No view was pinned on this page. Work on a copy to add one.':'Pin a view in Viewfinder, then change a setting to compare.'}</p>${drawing(s,w.view,'Current practice view')}`}<p>${esc(s.annotation)}</p>`:`${w.photoShown?`${photo(s,w,readonly?'':`<section class="lens-photo-controls"><h3>Enlarge the recorded pixels</h3><div class="lens-actions">${s.photo.zooms.map(z=>button(`data-lens-photo-zoom="${z}" aria-pressed="${w.photoView.zoom===z}"`,z===1?'Whole photo':`Enlarge ${z} times`,w.photoView.zoom===z)).join('')}</div>${arrows('data-lens-photo-pan')}</section>`)}`:readonly?'<p>No photograph was opened on this kept view. Work on a copy to open it.</p>':button('data-lens-photo','Open photograph')}`}${a.turn!==2?`<details data-lens-help${a.help?' open':''}><summary>Try a worked view</summary><p>Your own view and pin stay as you made them.</p>${w.exampleSeen?s.teaching.slice(0,w.exampleSeen).map((t,i)=>`<section class="lens-worked"><p>${esc(t.text)}</p>${drawing(s,t.view,`Worked view ${i+1}`)}</section>`).join(''):readonly?'<p>No help was opened on this kept view. Work on a copy to explore it.</p>':'<p>Open one step at a time when you want a hand.</p>'}${readonly?'':button(`data-lens-example${w.exampleSeen===s.teaching.length?' disabled':''}`,w.exampleSeen===0?'Show a worked view':w.exampleSeen===s.teaching.length?'All worked views shown':'Next worked view')}</details><details data-lens-limits${a.limits?' open':''}><summary>About this practice model</summary><p>${esc(s.context)}</p><p>${esc(s.notice)}</p><p>Marks in this drawing: ${esc(s.marks.map(m=>m.label).join(', '))}.</p></details>`:''}<details data-lens-credit${a.credit?' open':''}><summary>Photograph source and credit</summary><p>Photographer’s title: ${esc(s.photo.sourceTitle)}</p><p>${esc(s.photo.credit)} ${esc(s.photo.license)}</p><p>${esc(s.photo.captureLabel)}</p><p>${esc(s.photo.notice)}</p><p><a href="https://www.flickr.com/photos/146824358@N03/33605021164/" target="_blank" rel="noopener noreferrer">Original photograph and author credit</a> · <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 dedication</a></p></details>`;}
function shelf(v){const view=lensViewsView(v.book),items=view.items,total=items.length;if(v.page===null){const last=[...items].reverse().find(x=>x.readable);v.page=Math.floor((last?.index??Math.max(0,total-1))/8);}v.page=Math.max(0,Math.min(v.page,Math.max(0,Math.ceil(total/8)-1)));const start=v.page*8;return `<h2 id="lens-title" tabindex="-1">Kept views</h2><p>Frozen practice views, not scores.</p>${view.status==='unavailable'?'<p>This saved format cannot accept another view. Its original stays unchanged in your Notes download. Draft exploration is open.</p>':''}${total?`<p>Views ${start+1}–${Math.min(start+8,total)} of ${total}</p><ol start="${start+1}">${items.slice(start,start+8).map(x=>`<li>${x.readable?button(`data-lens-card="${esc(x.id)}"`,`View ${x.index+1} · ${x.raw.source.title}`):`<p>View ${x.index+1} · unavailable here. Its original stays unchanged in your Notes download.</p>`}</li>`).join('')}</ol><div class="lens-actions">${button(`data-lens-page="-1"${start===0?' disabled':''}`,'Previous views')}${button(`data-lens-page="1"${start+8>=total?' disabled':''}`,'Next views')}</div>`:'<p>Keep a practice view to leave it here. Any view can be kept, including a soft or empty-looking field.</p>'}`;}
export function lensBenchPage(book,owner){const v=state(book,owner);let body;if(v.screen==='shelf')body=shelf(v);else if(v.screen==='card'){const x=lensViewsView(book).items.find(x=>x.id===v.card&&x.readable);if(x){if(!v.readonly.has(x.id))v.readonly.set(x.id,makeSlot(x.raw.source,x.raw.work));body=`<p>View ${x.index+1}</p>`+activePage(slot(v),true,v.copies.has(x.id)?'Return to your copy':'Work on a copy');}else body='<h2 id="lens-title" tabindex="-1">This view is unavailable here</h2><p>Its original stays unchanged in your Notes download. Other views and drafts remain open.</p>';}else{if(!slot(v))draft(v,'crossed');body=activePage(slot(v));}return `<div class="lens-page" data-lens-root><header><div class="lens-actions">${button('data-lens-draft','Return to your view')}${button('data-lens-shelf','Kept views')}${button('data-lens-hear data-speak=""','Hear this page')}</div><h1>Lens Bench</h1></header>${body}<details data-lens-chooser${v.chooser?' open':''}><summary>Choose another practice pattern</summary><div class="lens-actions">${lensCases.map(c=>button(`data-lens-case="${esc(c.id)}"`,c.title,v.active===c.id&&v.screen==='draft')).join('')}</div></details><p class="lens-visit-note">Leaving or reloading loses views that have not been kept.</p></div>`;}
function speech(root){function read(n){if(n.nodeType===3)return n.textContent+' ';if(n.nodeType!==1||n.matches('svg,[hidden],[aria-hidden="true"],.speech-controls'))return '';if(n.matches('button'))return n.matches('[data-lens-card],[data-lens-case]')?n.textContent+' ':'';if(n.tagName==='DETAILS'&&!n.open)return '';if(n.matches('img[data-lens-photo-image]'))return n.alt+' ';return [...n.childNodes].map(read).join(' ');}return read(root).replace(/\s+/g,' ').trim();}
export function bindLensBench(book,ctx){const owner=()=>typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,v=state(book,owner()),screen=v.screen,active=v.active,card=v.card,held=slot(v),source=held?.source,work=held?.work,raw=screen==='card'?lensViewsView(book).items.find(x=>x.id===card&&x.readable)?.raw:null,rawSource=raw?.source,rawWork=raw?.work,root=document.querySelector('[data-lens-root]');if(!root)return;const live=n=>visit===v&&owner()===v.owner&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook)===book&&ctx.isActive()&&window.location.hash==='#science/lens'&&root.isConnected&&n.isConnected&&root.contains(n)&&v.screen===screen&&v.active===active&&v.card===card&&slot(v)===held&&held?.source===source&&held?.work===work&&(screen!=='card'||!raw||lensViewsView(book).items.some(x=>x.id===card&&x.readable&&x.raw===raw&&x.raw.source===rawSource&&x.raw.work===rawWork));const guard=n=>['click','pointerdown','change','input','toggle'].forEach(type=>n.addEventListener(type,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));guard(root);root.querySelectorAll('button,a[href],details,[data-lens-field],[data-speak]').forEach(guard);const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},redraw=(target='#lens-title')=>{ctx.render();ctx.focus(target);},on=(sel,fn)=>root.querySelectorAll(sel).forEach(n=>n.addEventListener('click',()=>{if(!live(n)||n.disabled)return;stop();fn(n);})),attr=(name,value)=>`[${name}="${CSS.escape(value)}"]`,update=(action,value)=>{if(screen!=='draft'||!held)return false;const next=changeLensWork(source,held.work,action,value);if(!next)return false;held.work=next;held.status='';return true;};on('[data-lens-draft]',()=>{v.screen='draft';if(!slot(v))draft(v,'crossed');redraw();});on('[data-lens-shelf]',()=>{v.screen='shelf';redraw();});on('[data-lens-case]',n=>{draft(v,n.dataset.lensCase);redraw();});on('[data-lens-card]',n=>{v.card=n.dataset.lensCard;v.screen='card';redraw();});on('[data-lens-page]',n=>{v.page+=Number(n.dataset.lensPage);redraw();});on('[data-lens-copy]',()=>{if(!raw)return;if(!v.copies.has(card)){const copy=makeSlot(raw.source,raw.work);Object.assign(copy,{turn:held.turn,help:held.help,limits:held.limits,credit:held.credit});v.copies.set(card,copy);}v.active=card;v.screen='draft';redraw();});on('[data-lens-turn]',n=>{held.turn=Number(n.dataset.lensTurn);redraw();});for(const [key,action,parse]of [['objective','objective',x=>x],['focus','focus',Number],['pan','pan',x=>x],['photoZoom','photoZoom',Number],['photoPan','photoPan',x=>x]]){const name='data-lens-'+key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());on(`[${name}]`,n=>{if(update(action,parse(n.getAttribute(name))))redraw(attr(name,n.getAttribute(name)));});}on('[data-lens-pin]',()=>{if(update('pin'))redraw('[data-lens-pin]');});on('[data-lens-photo]',()=>{if(update('photo'))redraw('#lens-title');});on('[data-lens-example]',()=>{if(update('example'))redraw(held.work.exampleSeen===source.teaching.length?'[data-lens-help] summary':'[data-lens-example]');});const field=root.querySelector('[data-lens-field]');field?.addEventListener('click',e=>{if(!live(field)||screen!=='draft')return;const matrix=field.getScreenCTM();if(!matrix)return;const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());if((point.x-200)**2+(point.y-200)**2>200**2)return;stop();if(update('tap',{x:point.x,y:point.y}))redraw('#lens-title');});for(const [name,key]of [['help','help'],['limits','limits'],['credit','credit'],['chooser','chooser']]){const n=root.querySelector(`[data-lens-${name}]`);n?.addEventListener('toggle',()=>{if(!live(n))return;stop();if(name==='chooser')v.chooser=n.open;else held[key]=n.open;});}on('[data-lens-keep]',()=>{if(screen!=='draft'||!held)return;const id=keepLensView(book,source,held.work,{canExport:ctx.canExport});if(!id){const view=lensViewsView(book);held.status=view.status==='unavailable'?'This saved format cannot accept another view. Its original stays unchanged in your Notes download. Your draft is still here.':!view.canKeep?'No new view number is available. Earlier views stay unchanged; this draft is still here.':'This view has not been kept. Earlier views stay unchanged in your Notes download. Your draft is still here for this visit.';}else{const saved=ctx.save();held.status=saved?.enabled===false?'This view is kept in this open page, but saving is off. Download Grown-up notes before closing to bring it back.':saved?.ok===false?'This view is kept in this open page, but device storage did not save. Download Grown-up notes before closing to bring it back.':'This view is kept. Find it in Kept views.';const kept=makeSlot(source,held.work);Object.assign(kept,{turn:held.turn,help:held.help,limits:held.limits,credit:held.credit,status:held.status});v.readonly.set(id,kept);v.card=id;v.screen='card';v.page=null;}redraw('#lens-status');});const hear=root.querySelector('[data-lens-hear]');hear?.addEventListener('click',()=>{if(live(hear))hear.dataset.speak=speech(root);},{capture:true});root.querySelectorAll('[data-lens-photo-image]').forEach(img=>{const fail=()=>{if(!live(img))return;img.hidden=true;img.nextElementSibling.hidden=false;};img.addEventListener('error',fail);if(img.complete&&img.naturalWidth===0)fail();});}
export function lensBenchEntry(){return `<section class="lens-entry"><h3>Lens Bench</h3><p>Find a marked practice pattern, compare views, and look at an onion-cell photograph.</p><a href="#science/lens">Open Lens Bench</a></section>`;}
export function lensCellInvitation(book,{open=false}={}){const last=lastLensView(book);if(!last)return `<section class="lens-cell"><h3>Look closer at a real image</h3><p>Explore marked practice drawings and an onion-cell photograph in <a href="#science/lens">Lens Bench</a>.</p></section>`;const {raw,index}=last,s=raw.source,w=raw.work;return `<details class="lens-cell" data-lens-cell-return${open?' open':''}><summary>Return to View ${index+1} · ${esc(s.title)}</summary>${drawing(s,w.view,'Kept practice view')}${w.pin?drawing(s,w.pin,'Kept pinned view'):'<p>No view was pinned in this kept record.</p>'}<p>${esc(s.annotation)}</p><p>${esc(s.notice)}</p><p>${esc(s.returnQuestion)}</p>${w.photoShown?`${photo(s,w)}<p>${esc(s.photoQuestion)}</p>`:'<p>No photograph was opened on this kept view.</p>'}<a href="#science/lens">Lens Bench → Kept views</a></details>`;}
